// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/users", wrapper.RegisterUser)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/users/login", wrapper.LoginUser)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/users/refresh-tokens", wrapper.RefreshTokens)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/users/logout", wrapper.LogoutUser)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/directory/entries", wrapper.RegisterDirectoryEntry)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/profile", wrapper.GetMyProfile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/me/profile", wrapper.CreateMyProfile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/media/uploads", wrapper.InitMediaUpload)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/media/uploads/{upload_id}/complete", wrapper.CompleteMediaUpload)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/media/{media_id}/url", wrapper.GetDownloadMediaUrl)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/conversations/direct", wrapper.StartDirectConversation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/conversations/{conversation_id}/messages", wrapper.SendMessage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/bff/web/home-page", wrapper.GetWebHomePage)
	})

	return r
}

